import{_ as r,o,c as n,a3 as a}from"./chunks/framework.DMtjdCb-.js";const e="/help/assets/release-radar.CDXZMHSP.png",s="/help/assets/resource-variants.C-EY7H9l.png",i="/help/assets/torrent-results.9GI06Rfo.png",u=JSON.parse('{"title":"4. 订阅与下载","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/subscribe.md","filePath":"zh-Hans/subscribe.md"}'),l={name:"zh-Hans/subscribe.md"};function g(d,t,h,p,c,_){return o(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="_4-订阅与下载" tabindex="-1">4. 订阅与下载 <a class="header-anchor" href="#_4-订阅与下载" aria-label="Permalink to &quot;4. 订阅与下载&quot;">​</a></h1><p>本章以《世界最强的魔女，就此开始》为例，完成一次资源选择与下载。Ani-RSS 订阅会继续跟踪后续更新；Torrent 下载则提交当前选定的资源。</p><h2 id="找到作品" tabindex="-1">找到作品 <a class="header-anchor" href="#找到作品" aria-label="Permalink to &quot;找到作品&quot;">​</a></h2><ol><li>在首页 <strong>标题 / 别名</strong> 输入作品名称，或打开 <strong>新作雷达</strong>。</li><li>在雷达中选择对应季度，点击作品标题，打开详情。</li><li>查看 <strong>Ani-RSS</strong> 资源区；需要刷新时点击资源检索按钮。</li></ol><p><img src="'+e+'" alt="新作雷达：按季度查看作品与更新" loading="lazy"></p><p>雷达中的 <strong>同步状态</strong> 获取 Ani-RSS 已知的订阅与媒体状态；<strong>检索资源</strong> 逐部查询该季度作品。检索在后台进行，进度会显示在页面上。</p><h2 id="选择-ani-rss-资源" tabindex="-1">选择 Ani-RSS 资源 <a class="header-anchor" href="#选择-ani-rss-资源" aria-label="Permalink to &quot;选择 Ani-RSS 资源&quot;">​</a></h2><ol><li>选择一个字幕组。</li><li>同组有多个版本时，用下拉框核对字幕、平台和画质，例如简体 / 繁体、Baha 等。</li><li>选中需要的资源，点击 <strong>启用订阅</strong>，在订阅确认页面核对资源组与版本，再次点击 <strong>启用订阅</strong>。</li><li>等待状态变为 <strong>已订阅</strong>，下载完成后在作品详情的播放区查看集数。</li></ol><p><img src="'+s+'" alt="选择资源：同一字幕组下继续选择具体版本" loading="lazy"></p><p><strong>完成标志：</strong> 作品显示已订阅，已有媒体的集数出现在播放区。后续新集由 Ani-RSS 继续获取，AnimeMachine 同步显示状态。</p><p>资源旁的“语言不符”“画质不符”等说明来自当前偏好。确实需要该版本时，可选择强行订阅，并在确认页面核对不符项目。</p><h2 id="尚未开播或等待收藏资源" tabindex="-1">尚未开播或等待收藏资源 <a class="header-anchor" href="#尚未开播或等待收藏资源" aria-label="Permalink to &quot;尚未开播或等待收藏资源&quot;">​</a></h2><p>在作品详情点击 <strong>资源跟踪</strong>，选择 <strong>提前订阅连载</strong>，保存后显示为 <strong>待资源</strong>。后台会定期检索，找到符合偏好的资源后自动启用 Ani-RSS 订阅；尚未连接 Ani-RSS 时，意向仍会保留。</p><p>默认使用设置中的资源组偏好。需要进一步限定时，取消勾选这一项，展开目标资源组，例如只勾选 <strong>Kirara Fantasia → Baha</strong>。已经存在的 Ani-RSS 订阅按原配置保留。</p><p>等待 BDRip 等收藏资源时，选择 <strong>跟踪收藏资源</strong>。发现资源后只提示，再由你核对版本并下载。所有记录可在新作雷达的 <strong>资源跟踪</strong> 中查看、调整或停止。</p><h2 id="使用-torrent-资源" tabindex="-1">使用 Torrent 资源 <a class="header-anchor" href="#使用-torrent-资源" aria-label="Permalink to &quot;使用 Torrent 资源&quot;">​</a></h2><ol><li>先在 <strong>设置 → 连接</strong> 确认 qBittorrent 可用。</li><li>在作品详情点击 <strong>检索 Torrent</strong>，等待查询完成。</li><li>展开 <strong>Torrent</strong> 结果，选择字幕组，再选择该组的字幕、画质等版本。</li><li>点击 <strong>预览下载计划</strong>，核对作品、文件和目标目录后确认提交。</li><li>打开 qBittorrent，选中刚加入的停止任务并开始下载。</li></ol><p><img src="'+i+'" alt="Torrent 结果：展开后选择字幕组及版本" loading="lazy"></p><p>本地 Torrent 计划以停止状态加入下载器，开始后才实际下载。连载作品会核对季度和集数，过滤串季、缺集及明显落后的资源；已完结作品与剧场版保留补收藏用途。</p><p>上百集的连载作品按每个版本最近 24 集的连续性检查，最多允许落后最新进度一集，避免要求一次找齐全部历史集数。收藏类版本仍可用于分批补全旧集。</p><h2 id="使用自己的-torrent-池" tabindex="-1">使用自己的 Torrent 池 <a class="header-anchor" href="#使用自己的-torrent-池" aria-label="Permalink to &quot;使用自己的 Torrent 池&quot;">​</a></h2><p>在 <strong>设置 → 连接 → Torrent Collector</strong> 中，作品检索和资源池可以分别使用：</p><table tabindex="0"><thead><tr><th>使用方式</th><th>配置方法</th></tr></thead><tbody><tr><td>临时找一部作品</td><td>在详情点击 <strong>检索 Torrent</strong>；无需单独运行采集器</td></tr><tr><td>已经维护了 <code>.torrent</code> 文件目录</td><td>填写 <strong>Torrent 池路径</strong>，启用 <strong>定时扫描资源池</strong></td></tr><tr><td>自动补充种子池</td><td>联合部署 Torrent Collector，并启用 <strong>自动采集 Torrent</strong></td></tr></tbody></table><p>只使用现成种子池时，可以关闭自动采集，保留定时扫描。三种方式共用资源偏好，结果都在作品详情选择；文件清单与下载目录在提交前确认。</p><h2 id="下载还没有开始" tabindex="-1">下载还没有开始 <a class="header-anchor" href="#下载还没有开始" aria-label="Permalink to &quot;下载还没有开始&quot;">​</a></h2><p>先在 AnimeMachine 查看连接与任务状态，再到 qBittorrent 查看该任务是否有可连接的做种者。资源已经提交但暂时没有速度，与“尚未提交下载”是不同状态。<a href="./troubleshooting.html#download">常见问题</a>列出了检查顺序。</p>',26)])])}const m=r(l,[["render",g]]);export{u as __pageData,m as default};
